            eprintln!("  curl -L -o models/tinydecide/model.bin https://huggingface.co/TheREZOR/TinyDecide/resolve/main/model.bin");
            return;
        };
        let provider = TinyDecideProvider::load(&dir).expect("tinydecide load failed");

        let cases = [
