            ("lower the brightness", Intent::Command),
            ("mute the speaker", Intent::Command),
            ("open vs code", Intent::Command),
            ("open app store", Intent::Command),
            (
                "the file is in the downloads folder and i need you to check it out",
                Intent::Dictation,
