                Intent::Dictation,
            ),
        ];

        let mut correct = 0;
        for (text, expected) in &cases {
            let got = provider.classify_intent(text);
            let ok = got == *expected;
            if ok {
                correct += 1;
            }
            println!(
                "  {:<55} → {:<12} (expected {:<12} {})",
                text,
                got.label(),
                expected.label(),
                if ok { "✓" } else { "✗" }
